  static string Hash(byte[] b){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(b)).Replace("-","").ToLowerInvariant();}
  public static string ResolveSave(Engine e,string id){if(string.IsNullOrWhiteSpace(id)||id.Length>260||id.Contains('\\')||id.Contains(':'))throw new Exception("无效存档标识。");string[] parts=id.Split('/');if(parts.Length!=2||parts.Any(part=>part.Length==0||part=="."||part==".."||part.EndsWith(".")||part.EndsWith(" ")||part.IndexOfAny(Path.GetInvalidFileNameChars())>=0))throw new Exception("无效存档标识。");string root=Path.GetFullPath(Path.Combine(e.User,"Saves")),p=Path.GetFullPath(Path.Combine(root,parts[0],parts[1]));if(!p.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("存档路径越界。");Safe(p);if(!Directory.Exists(p))throw new Exception("存档不存在，请刷新。");return p;}
