  static string Stamp(Engine e,Document d,bool inherited){return (inherited?"inherited:":"file:")+Hash(d.Bytes)+":"+Hash(DefaultBytes(e)??new byte[0]);}
  internal static string ConfigurationStamp(Engine e,string id){bool inherited;var document=Load(e,ResolveSave(e,id),out inherited);return Stamp(e,document,inherited);}
public static object Read(Engine e,string id,bool captured=false){string path=ResolveSave(e,id);bool inherited;var d=Load(e,path,out inherited,captured);return new{id=id,name=Path.GetFileName(path),mode=id.Split('/')[0],modifiedUtc=Directory.GetLastWriteTimeUtc(path).ToString("o"),stamp=Stamp(e,d,inherited),enabled=LaunchProfiles.PersistentMods(e,d.Mods),supportIds=e.FrozenEnvironment!=null?e.FrozenEnvironment.DefaultModIds:e.OwnedLaunch?e.OwnedComponents().Installations(CancellationToken.None).Where(row=>row.Enabled).Select(row=>row.Id).ToArray():DefaultMods(DefaultBytes(e)),snapshotBound=e.FrozenEnvironment!=null,snapshotId=e.FrozenEnvironment==null?null:e.FrozenEnvironment.Id,snapshotName=e.FrozenEnvironment==null?null:e.FrozenEnvironment.Name,maps=d.Maps,requiresConfirmation=inherited,warnings=inherited?new[]{"存档缺少 mods.txt，当前显示实际默认模组；确认后才创建存档配置。"}:new string[0]};}
  internal static string[] LaunchMods(Engine e,string id,LaunchReadBudget budget){string path=Path.Combine(ResolveSave(e,id),"mods.txt");var bytes=budget.Read(path,MaxText);var d=Parse(bytes??budget.Read(e.Mods,MaxText)??Utf8.GetBytes("mods\n{\n}\nmaps\n{\n}\n"));var ids=ModConfigurations.ValidatePreflightMods(d.Mods);string remaining=Regex.Replace(d.Block.Groups[1].Value,@"(?m)^\s*mod\s*=\s*([^,\r\n]+)\s*,\s*$","");if(!string.IsNullOrWhiteSpace(remaining))throw new Exception("当前存档 mods 块含未知语法，请在游戏内核实。");return e.FrozenEnvironment==null?ids:SnapshotModChoices.Apply(ids,e.FrozenEnvironment.ModChoices);}
  public static void ValidateForLaunch(Engine e,string id){bool inherited;var d=Load(e,ResolveSave(e,id),out inherited);if(d.Mods.Any(m=>!Id(m))||d.Mods.Distinct(StringComparer.Ordinal).Count()!=d.Mods.Length)throw new Exception("当前存档包含无效或重复模组 ID。");string remaining=Regex.Replace(d.Block.Groups[1].Value,@"(?m)^\s*mod\s*=\s*([^,\r\n]+)\s*,\s*$","");if(!string.IsNullOrWhiteSpace(remaining))throw new Exception("当前存档 mods 块含未知语法，请在游戏内核实。");var result=ModConfigurations.SortForSave(e,d.Mods);if(result.errors.Length>0||result.violations.Length>0)throw new Exception(string.Join("\n",result.errors.Concat(result.violations)));}
  public static object List(Engine e){
   var warnings=new List<string>();var rows=new List<object>();string root=Path.Combine(e.User,"Saves");
   foreach(string mode in Dirs(root,warnings))foreach(string path in Dirs(mode,warnings)){
    string id=Path.GetFileName(mode)+"/"+Path.GetFileName(path),resolved;try{resolved=ResolveSave(e,id);}catch(Exception error){warnings.Add(id+"："+error.Message);continue;}
    int? count=null;string warning="";try{bool inherited;count=Load(e,resolved,out inherited).Mods.Length;}catch(Exception error){if(error is OperationCanceledException||error is OutOfMemoryException||error is StackOverflowException)throw;warning="模组清单无法读取，存档文件已保留。 "+error.Message;warnings.Add(id+"："+warning);}
