   }return new{saves=rows,warnings=warnings};
  }
  internal static bool Id(string s){return !string.IsNullOrWhiteSpace(s)&&s.Length<=200&&!s.Any(c=>char.IsControl(c)||c==','||c==';'||c=='='||c=='{'||c=='}');}
  internal static byte[] DefaultBytes(Engine e){Safe(e.Mods);return File.Exists(e.Mods)?Bytes(e.Mods):null;}
  internal static string[] DefaultMods(byte[] bytes){return Parse(bytes??Utf8.GetBytes("VERSION = 1,\nmods\n{\n}\nmaps\n{\n}\n")).Mods;}
  internal static byte[] ReplaceDefaultMods(byte[] bytes,string[] mods){var d=Parse(bytes??Utf8.GetBytes("VERSION = 1,\nmods\n{\n}\nmaps\n{\n}\n"));string body=d.Block.Groups[1].Value;string remaining=Regex.Replace(body,@"(?m)^\s*mod\s*=\s*([^,\r\n]+)\s*,\s*$","");if(!string.IsNullOrWhiteSpace(remaining))throw new Exception("mods 块含未知语法，未修改。");string nl=d.Text.Contains("\r\n")?"\r\n":"\n";string replacement=nl+string.Concat(mods.Select(m=>"    mod = "+m+","+nl));int start=d.Block.Groups[1].Index;byte[] output=Utf8.GetBytes(d.Text.Substring(0,start)+replacement+d.Text.Substring(start+body.Length));return d.Bom?new byte[]{239,187,191}.Concat(output).ToArray():output;}
  public static object Save(Engine e,string id,string stamp,string[] mods,bool confirmed,bool captured=false){e.GuardContent();string path=ResolveSave(e,id);string name="Local\\OrangeSaveProfiles-"+Hash(Utf8.GetBytes(Path.GetFullPath(Path.Combine(path,"mods.txt")).ToUpperInvariant()));using(var mutex=new Mutex(false,name)){bool held=false;try{try{held=mutex.WaitOne(5000);}catch(AbandonedMutexException){held=true;}if(!held)throw new Exception("存档配置正被其他窗口修改，请稍后重试。");using(PlayProfileTransaction.Lock(e)){return SaveLocked(e,id,stamp,mods,confirmed,path,captured);}}finally{if(held)mutex.ReleaseMutex();}}}
  static object SaveLocked(Engine e,string id,string stamp,string[] mods,bool confirmed,string path,bool captured){e.GuardContent();Safe(path);if(id.Split('/')[0].Equals("Multiplayer",StringComparison.OrdinalIgnoreCase))throw new Exception("联机存档只读。");bool inherited;var d=Load(e,path,out inherited,captured);if(Stamp(e,d,inherited)!=stamp)throw new Exception("配置已被其他程序修改，请刷新。");if(mods!=null)mods=mods.Select(m=>m==null?null:m.Trim()).ToArray();if(mods==null||mods.Length>2000||mods.Any(m=>!Id(m))||mods.Distinct(StringComparer.Ordinal).Count()!=mods.Length)throw new Exception("无效或重复的模组 ID。");if(!inherited&&mods.SequenceEqual(LaunchProfiles.PersistentMods(e,d.Mods)))return Read(e,id,captured);if(!confirmed&&(inherited||d.Mods.Except(mods).Any()))throw new Exception("创建独立配置或移除模组需要明确确认。");
   string body=d.Block.Groups[1].Value;string remaining=Regex.Replace(body,@"(?m)^\s*mod\s*=\s*([^,\r\n]+)\s*,\s*$","");if(!string.IsNullOrWhiteSpace(remaining))throw new Exception("mods 块含未知语法，未修改。");string nl=d.Text.Contains("\r\n")?"\r\n":"\n";string newBody=nl+string.Concat(mods.Select(m=>"    mod = "+m+","+nl));int start=d.Block.Groups[1].Index;string text=d.Text.Substring(0,start)+newBody+d.Text.Substring(start+body.Length);byte[] output=Utf8.GetBytes(text);if(d.Bom)output=new byte[]{239,187,191}.Concat(output).ToArray();string file=Path.Combine(path,"mods.txt"),temp=file+".orange-"+Guid.NewGuid().ToString("N")+".tmp";try{Safe(temp);File.WriteAllBytes(temp,output);e.GuardContent();Safe(file);bool nowInherited;var now=Load(e,path,out nowInherited,captured);if(Stamp(e,now,nowInherited)!=stamp)throw new Exception("配置已被其他程序修改，请刷新。");if(inherited)File.Move(temp,file);else File.Replace(temp,file,null);}finally{if(File.Exists(temp))File.Delete(temp);}return Read(e,id,captured);}
  static void Validate(string[] ids,List<Entry> entries){var lookup=entries.GroupBy(m=>m.id,StringComparer.Ordinal).ToDictionary(g=>g.Key,g=>g.ToArray(),StringComparer.Ordinal);var positions=ids.Select((id,i)=>new{id,i}).ToDictionary(x=>x.id,x=>x.i,StringComparer.Ordinal);foreach(string id in ids){if(!lookup.ContainsKey(id)||lookup[id].Length!=1)throw new Exception("模组缺失或 ID 冲突："+id);foreach(string dep in lookup[id][0].requires){if(!positions.ContainsKey(dep))throw new Exception("缺少依赖："+id+" → "+dep);if(positions[dep]>=positions[id])throw new Exception("依赖顺序或循环错误："+id+" → "+dep);}}}
  internal sealed class CatalogSnapshot {internal List<Entry> Entries;internal object Catalog;}
  internal static void InvalidateDisplay(Engine e){DisplayCache.Invalidate(e);}
  internal static CatalogSnapshot DisplaySnapshot(Engine e,CancellationToken token=default(CancellationToken),Action<int,string> progress=null){token.ThrowIfCancellationRequested();return DisplayCache.Read(e,"catalog",()=>{var w=new List<string>();LaunchReadBudget budget=null;if(token.CanBeCanceled){budget=new LaunchReadBudget(67108864,100000);int count=0;budget.Checkpoint=(file,fileBytes)=>{token.ThrowIfCancellationRequested();count++;if(progress!=null&&(count==1||count%20==0))progress(-1,"正在扫描模组 · 已读取 "+count+" 项");};}var entries=Entries(e,w,false,budget);token.ThrowIfCancellationRequested();var managed=new HashSet<string>(ModConfigurations.Managed(entries.Select(entry=>entry.id.TrimStart('\\')).ToArray()),StringComparer.Ordinal);var json=new JavaScriptSerializer{MaxJsonLength=2097152};var rows=new List<Entry>();int size=0;foreach(var entry in entries){entry.componentManaged=managed.Contains(entry.id.TrimStart('\\'));int length=json.Serialize(entry).Length;if(size+length>1400000){w.Add("模组目录超过单次显示限制；部分条目未显示。");break;}rows.Add(entry);size+=length;}return new CatalogSnapshot{Entries=entries,Catalog=new{mods=rows,warnings=w.Select(s=>Bound(s,512)).Distinct(StringComparer.Ordinal).Take(100).ToArray()}};});}
  public static object Catalog(Engine e){return DisplaySnapshot(e).Catalog;}
  internal static object Catalog(Engine e,CancellationToken token,Action<int,string> progress){return DisplaySnapshot(e,token,progress).Catalog;}
  static string Bound(string text,int length){return text.Length<=length?text:text.Substring(0,length);}
  public static object Cover(Engine e,string token){if(token==null||!Regex.IsMatch(token,"^[a-f0-9]{64}$"))throw new Exception("无效封面标识。");var matches=DisplaySnapshot(e).Entries.Where(x=>x.coverToken==token).ToArray();if(matches.Length!=1)throw new Exception("封面不存在或标识冲突，请刷新目录。");var entry=matches[0];return new{token=token,cover=ReadCover(entry.posterRoot,entry.poster,new List<string>())};}
  // Keep catalog bodies bounded. Only the expanded source's common/active files
  // are reopened; full descriptions never become display-cache values.
  public static object Detail(Engine e,string token,CancellationToken cancellation=default(CancellationToken)){
   if(token==null||!Regex.IsMatch(token,@"\A[a-f0-9]{64}\z"))throw new IOException("无效模组详情标识。");
   cancellation.ThrowIfCancellationRequested();var matches=DisplaySnapshot(e,cancellation).Entries.Where(x=>x.coverToken==token).ToArray();if(matches.Length!=1)throw new IOException("模组来源不存在或标识冲突，请刷新目录。");var entry=matches[0];
   var budget=new LaunchReadBudget(2L*MaxText);budget.Checkpoint=(file,bytes)=>cancellation.ThrowIfCancellationRequested();
   byte[] common=entry.commonInfoRoot==null?null:budget.Read(Path.Combine(entry.commonInfoRoot,"mod.info"),MaxText),active=budget.Read(Path.Combine(entry.infoRoot,"mod.info"),MaxText);
   if((Identity(active)??Identity(common))!=entry.id)throw new IOException("模组来源已改变，请刷新目录后重新查看。");
