  internal sealed class PreflightCatalog {
   internal readonly List<Entry> Entries=new List<Entry>();
   internal readonly HashSet<string> KnownIds=new HashSet<string>(StringComparer.Ordinal);
   internal readonly List<Candidate> Candidates=new List<Candidate>();
   readonly HashSet<string> expanded=new HashSet<string>(StringComparer.Ordinal);
   readonly HashSet<Candidate> materialized=new HashSet<Candidate>();
   internal void Select(IEnumerable<string> ids,IDictionary<string,string> choices=null){
    var pending=new Queue<string>(SnapshotModChoices.Apply(ids,choices));
    while(pending.Count>0){
     string id=pending.Dequeue();if(!expanded.Add(id))continue;
     var matches=Candidates.Where(c=>c.Id==id).ToArray();
     if(matches.Length==0)matches=Candidates.Where(c=>c.Id==id.TrimStart('\\')).ToArray();
     foreach(var candidate in matches){
      if(!materialized.Add(candidate))continue;
      var entry=DescribeCandidate(candidate);
      entry.requires=entry.require=SnapshotModChoices.Apply(entry.requires,choices);Entries.Add(entry);foreach(string dependency in entry.requires)pending.Enqueue(dependency);
     }
    }
   }
  }
  internal static Entry DescribeCandidate(Candidate candidate){var values=ParseInfo(candidate.Common);foreach(var pair in ParseInfo(candidate.Active))values[pair.Key]=pair.Value;return MakeEntry(candidate.Root,candidate.Source,candidate.Workshop,candidate.Layout,candidate.CommonRoot,values,new List<string>(),false);}
  internal sealed class Candidate {internal string Id,Root,Source,Workshop,Layout,CommonRoot;internal byte[] Common,Active;}
  internal static PreflightCatalog SnapshotEntries(Engine e,string[] mods,List<string> warnings,LaunchReadBudget budget,IDictionary<string,string> choices=null,bool ownSelection=false){budget=budget??new LaunchReadBudget(67108864,100000);var catalog=new PreflightCatalog();Collect(e,warnings,false,budget,catalog);if(ownSelection&&e.OwnedLaunch){var components=e.OwnedComponents();var selected=components.CaptureCurrent(CancellationToken.None,SnapshotModChoices.Apply(mods??components.OrdinaryIds(),choices)).Rows.Where(row=>row.Enabled&&!string.IsNullOrEmpty(row.SourceRoot)).ToArray();var managed=components.ManagedIds();catalog.Candidates.RemoveAll(row=>(managed.Contains(row.Id)||selected.Any(item=>item.Id==row.Id))&&!selected.Any(item=>item.Id==row.Id&&VersionLibrary.Same(item.SourceRoot,row.Root)));}catalog.Select(mods??new string[0],choices??(e.FrozenEnvironment==null?null:e.FrozenEnvironment.ModChoices));return catalog;}
  internal static PreflightCatalog PreflightEntries(Engine e,string[] mods,List<string> warnings,LaunchReadBudget budget){budget=budget??new LaunchReadBudget(16777216);var catalog=new PreflightCatalog();Collect(e,warnings,true,budget,catalog);catalog.Select(mods??new string[0],e.FrozenEnvironment==null?null:e.FrozenEnvironment.ModChoices);return catalog;}
  // Each consumed directory and mod.info validates its complete ancestor path at
  // its read boundary. Unused media/poster directories need no catalog traversal.
