  static Dictionary<string,string> ParseInfo(byte[] bytes){var values=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);if(bytes==null)return values;bool bom;foreach(string line in Decode(bytes,out bom).Split('\n')){int eq=line.IndexOf('=');if(eq>0)values[line.Substring(0,eq).Trim()]=line.Substring(eq+1).Trim();}return values;}
