  static List<Entry> Collect(Engine e,List<string> w,bool knownPathsOnly,LaunchReadBudget budget,PreflightCatalog selection,bool presentation=true){Version current=Current(e,w);if(e.FrozenEnvironment!=null){var frozen=new List<Entry>();var visited=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var root in e.FrozenEnvironment.ModRoots)Add(root.CopiedRoot,"snapshot",root.WorkshopId,current,frozen,w,visited,budget,selection,presentation);return frozen;}if(selection!=null)budget.Expect(()=>{if(Current(e,new List<string>())!=current)throw new IOException("游戏版本在检查期间改变，请重新启动。");});var result=new List<Entry>();budget=selection!=null?(budget??new LaunchReadBudget(67108864,100000)):knownPathsOnly?(budget??new LaunchReadBudget(16777216)):budget;var roots=new List<string>{e.Workshop};var selectedWorkshops=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);var selectedRoots=new List<string>(new[]{e.BuddySource,e.ViewSource,e.ModelsSource}.Where(s=>!string.IsNullOrEmpty(s)));if(e.OwnedLaunch)selectedRoots.AddRange(e.OwnedComponents().List(CancellationToken.None).Select(row=>row.SourceRoot));if(knownPathsOnly||selection!=null){string cache=Path.Combine(e.Data,"workshop-paths.json");Safe(cache);if(selection!=null)budget.ObserveMissing(cache);if(File.Exists(cache)){byte[] cacheBytes;try{cacheBytes=Bytes(cache,budget);}catch(LaunchReadBudget.Exhausted){w.Add("工坊来源记录未在累计读取预算内核实；已保留可安全检查的已知目录。");cacheBytes=null;}if(cacheBytes!=null){Dictionary<string,string> paths;try{paths=new JavaScriptSerializer{MaxJsonLength=MaxText,RecursionLimit=8}.Deserialize<Dictionary<string,string>>(Utf8.GetString(cacheBytes));}catch(ArgumentException){throw new Exception("已记录工坊来源数据格式无效，无法完成模组依赖检查。");}catch(InvalidOperationException){throw new Exception("已记录工坊来源数据格式无效，无法完成模组依赖检查。");}if(paths==null||paths.Count>2000||paths.Values.Any(p=>string.IsNullOrWhiteSpace(p)||!Path.IsPathRooted(p)))throw new Exception("已记录工坊来源无效或超出数量限制。");selectedRoots.AddRange(paths.Values);foreach(var pair 