  static void Add(string root,string source,string workshop,Version current,List<Entry> result,List<string> w,HashSet<string> seen,LaunchReadBudget budget=null,PreflightCatalog selection=null,bool presentation=true){try{if(selection==null)Safe(root);if(selection==null&&!Directory.Exists(root)||!seen.Add(Path.GetFullPath(root)))return;var dirs=selection==null?Dirs(root,w,budget):IdentityDirs(root,w,budget);string common=current.Major<42?null:dirs.FirstOrDefault(d=>Path.GetFileName(d).Equals("common",StringComparison.OrdinalIgnoreCase));var candidates=new List<KeyValuePair<Version,string>>();foreach(string d in dirs){string name=Path.GetFileName(d);Version v;if(name=="42")v=new Version(42,0);else if(!Version.TryParse(name,out v))continue;if(current.Major>=42&&v.Major==current.Major&&v<=current)candidates.Add(new KeyValuePair<Version,string>(v,d));}string active=candidates.OrderByDescending(c=>c.Key).Select(c=>c.Value).FirstOrDefault();if(active==null){if(current.Major>=42){if(common==null)return;active=Path.Combine(root,current.Major.ToString(System.Globalization.CultureInfo.InvariantCulture)+".0");}else active=root;}
