  static Entry MakeEntry(string root,string source,string workshop,string active,string common,Dictionary<string,string> values,List<string> w,bool presentation,string posterRoot=null){string id=Value(values,"id");posterRoot=posterRoot??common??active;string[] requires=LauncherComponents.Dependencies(id,Edges(values,"require"));string poster=Value(values,"poster"),title=Bound(Value(values,"name")==""?id:Value(values,"name"),200);Dictionary<string,string> original=null;if(presentation){original=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(var pair in values.Take(64))original[Bound(pair.Key,100)]=Bound(pair.Value,256);if(values.Count>64||values.Any(p=>p.Key.Length>100||p.Value.Length>256))w.Add("作者元数据超过显示限制；目录保留有界原文摘要。");}return new Entry{id=id,name=title,title=title,author=Bound(Value(values,"author"),200),description=Bound(Value(values,"description"),512),version=Bound(Value(values,"modversion")==""?Value(values,"version"):Value(values,"modversion"),100),source=source,workshopId=workshop,item=workshop,posterRoot=posterRoot,poster=poster,infoRoot=active,commonInfoRoot=common,hasCover=presentation&&PosterPath(posterRoot,poster,w)!=null,coverToken=Hash(Utf8.GetBytes(Path.GetFullPath(root).ToUpperInvariant()+"\n"+id+"\n"+active.ToUpperInvariant()+"\n"+source)),requires=requires,require=requires,loadAfter=Edges(values,"loadAfter","loadModAfter"),loadBefore=Edges(values,"loadBefore","loadModBefore"),conflicts=Edges(values,"conflicts","incompatible"),metadata=original,javaComponent=JavaComponents.HasJavaMetadata(values),installationComponent=LauncherComponents.InstallationComponent(id),requiresBuddy=!LauncherComponents.InstallationComponent(id)&&(JavaComponents.HasJavaMetadata(values)||requires.Contains("ZombieBuddy")),conflict=false,map=Directory.Exists(Path.Combine(active,"media/maps"))||(common!=null&&Directory.Exists(Path.Combine(common,"media/maps")))};}
  static string[] Edges(Dictionary<string,string> values,params string[] keys){return keys.SelectMany(key=>Value(values,key).Split(new[]{',',';'},StringSplitOptions.RemoveEmptyEntries)).Select(s=>s.Trim().TrimStart('\\')).Where(s=>s.Length>0).Distinct(StringComparer.Ordinal).ToArray();}
  static string PosterPath(string root,string poster,List<string> w){if(poster=="")return null;try{if(Path.IsPathRooted(poster)||poster.IndexOfAny(new[]{'\\','/',':'})>=0||poster=="..")throw new Exception("封面路径无效。");string p=Path.Combine(root,poster);Safe(p);if(!File.Exists(p)){Version layout;if(Path.GetFileName(root)=="42"||Version.TryParse(Path.GetFileName(root),out layout)){p=Path.Combine(Path.GetDirectoryName(root),"common",poster);Safe(p);}if(!File.Exists(p))return null;}return p;}catch(Exception x){w.Add(x.Message);return null;}}
  static string ReadCover(string root,string poster,List<string> w){try{string p=PosterPath(root,poster,w);if(p==null)return "";long size=new FileInfo(p).Length;if(size==0||size>MaxCover)throw new Exception("封面超出大小限制。");byte[] b=File.ReadAllBytes(p);if(b.Length>MaxCover)throw new Exception("封面超出大小限制。");string mime;if(b.Length>=8&&b.Take(8).SequenceEqual(new byte[]{137,80,78,71,13,10,26,10}))mime="image/png";else if(b.Length>=3&&b[0]==255&&b[1]==216&&b[2]==255)mime="image/jpeg";else throw new Exception("封面格式无效。");using(var stream=new MemoryStream(b))using(var image=Image.FromStream(stream,false,true)){if(image.Width>4096||image.Height>4096)throw new Exception("封面尺寸过大。");}return "data:"+mime+";base64,"+Convert.ToBase64String(b);}catch(Exception x){w.Add(x.Message);return "";}}
